window.QUESTIONS.push(...[{"id":"110-1-A-26","exam":"110-1","q":26,"unit":"經濟學","topic":"經濟學","stem":"下列敘述何者正確？","options":["人們為滿足慾望，支付代價而取得財貨及勞務的行為稱為需求","人們對財貨產生缺乏之感與求足之願的心理狀態稱為消費","效用是一種客觀的概念，會因人、時、地的差異而不同","一般而言財貨的用途愈多，其邊際效用遞減的速度愈慢"],"answer":"D","official":"(A) 人們為滿足慾望，支付代價而取得財貨及勞務的\n行為稱為消費\n(B) 人們對財貨產生缺乏之感與求足之願的心理狀態\n稱為慾望\n(C) 效用是一種主觀的概念，會因人、時、地的差異\n而不同"},{"id":"110-1-A-27","exam":"110-1","q":27,"unit":"經濟學","topic":"經濟學","stem":"下列敘述何者錯誤？","options":["通常已開發國家的恩格爾係數，較未開發國家大","生產要素中，土地是大自然所賜與的自然資源","生產要素中，個別勞動者具有供給曲線向後彎的特質","在自由經濟社會中，消費者的意向為經濟活動的指標"],"answer":"A","official":"(A) 通常已開發國家恩格爾係數較未開發國家小"},{"id":"110-1-A-28","exam":"110-1","q":28,"unit":"經濟學","topic":"經濟學","stem":"下列敘述何者錯誤？","options":["報酬遞減法則屬於短期概念，此處的短期是指一年或一個營業週期以內的期間","經濟成長及經濟穩定之經濟問題，可藉由政府擬訂適當的政策來解決","消費者有了解產品的性能、成分…等事實真相的權利是為求知的權利","工廠引進機器來代替人工作業，以提高效率、節省人工成本是屬於如何生產的經濟問題"],"answer":"A","official":"(A) 報酬遞減法則屬於短期概念，此處的短期是指有\n固定要素存在的情形"},{"id":"110-1-A-29","exam":"110-1","q":29,"unit":"經濟學","topic":"經濟學","stem":"下列敘述何者正確？","options":["飲料、汽油、食物等僅可供一次性消費的財貨，稱為消耗財","百貨公司推出「換季大拍賣」，主要原因為需求增加","先製造機器、工具，再利用這些機器、工具生產消費財的生產方式為大規模生產","經濟學(Economics)是一門研究人類經濟行為的自然科學"],"answer":"A","official":"(B) 百貨公司在秋冬推出「夏季服飾大拍賣」，是因消\n費者需求減少，以降價刺激購買慾\n(C) 先製造機器、工具，再利用這些機器、工具生產\n消費財的生產方式為迂迴生產\n(D) 經濟學(Economics)是一門研究人類經濟行為的\n社會科學"},{"id":"110-1-A-30","exam":"110-1","q":30,"unit":"經濟學","topic":"經濟學","stem":"下列敘述何者正確？","options":["以市場自由經濟為主，政府參與經濟運作為輔的經濟制度稱為資本主義經濟制度","凱因斯所提出「貧窮於富裕之中」是指在富裕的表徵下，隱藏著貧富懸殊、分配不均的嚴重問題","規範經濟學又稱「唯真經濟學」","馬爾薩斯的「人口論」在說明糧食的增加速度大於人口增加的速度"],"answer":"B","official":"(A) 以市場自由經濟為主，政府參與經濟運作為輔的\n經濟制度稱為混合經濟制度\n(C) 規範經濟學又稱「唯善經濟學」\n(D) 馬爾薩斯的「人口論」在說明糧食的增加速度小\n於人口增加的速度"},{"id":"110-1-A-31","exam":"110-1","q":31,"unit":"經濟學","topic":"經濟學","stem":"下列敘述何者正確？","options":["近年來，民宿業蓬勃發展，顯示遊客對民宿的需求殷切，這種需求是為間接需求","目前世界大部分國家是實施混合經濟制度","生產可能曲線上的各點均符合經濟效率","經濟財是指可以長期使用的財貨"],"answer":"B","official":"(A) 消費者對民宿的需求，是直接需求，也是最後需求\n(C) 生產可能曲線上的各點符合生產效率\n(D) 經濟財是指必需付出代價才可以使用的財貨"},{"id":"110-1-A-32","exam":"110-1","q":32,"unit":"經濟學","topic":"經濟學","stem":"下列敘述有幾項錯誤？\n①政府對一般產品進行價格上限管制，會產生「短缺」，很容易導致黑市價格\n②經濟問題發生的主要原因為私有財產制\n③1970 年代主張「減稅」以刺激生產的學者為拉佛爾(Arthur B. Laffer)\n④市場經濟制度最強調的是消費機能","options":["一項","二項","三項","四項"],"answer":"B","official":"②稀少性(即資源有限、慾望無窮)是經濟問題發生的\n主因\n④市場經濟制度最強調的是價格機能"},{"id":"110-1-A-33","exam":"110-1","q":33,"unit":"經濟學","topic":"經濟學","stem":"假設其他條件不變，下列何者表示消費者對該財貨的需求彈性等於一？\n①蘋果漲價 20%，小林對蘋果的購買量減少 20%\n②小王不管菜價漲或跌，每天都買 500 元的蔬菜，料理三餐\n③小李不論飲料漲或跌，每天都買三杯飲料來喝\n④醫院收費漲價 10%，使醫院的總收益(TR)增加 10%","options":["①②","①④","②③","③④"],"answer":"A","official":"① d\n% 20% E1\n% 20%\n− ＝ ＝＝ 需求量變化\n價格變化\n②不論價格漲跌，支出額保持不變， E1 d ＝\n③購買量固定 3 杯，是需求量保持不變\n→需求量變化% ＝ 0 → E0 d ＝\n④TR 與價格成同方向同比例變化，是需求量保持不\n變→需求量變化% ＝ 0 → E0 d ＝"},{"id":"110-1-A-34","exam":"110-1","q":34,"unit":"經濟學","topic":"經濟學","stem":"水的價格比鑽石低，是因為下列何者？","options":["鑽石比較有用","水的平均效用比鑽石的平均效用低","水的總效用比鑽石的總效用低","水的邊際效用比鑽石的邊際效用低"],"answer":"D"},{"id":"110-1-A-35","exam":"110-1","q":35,"unit":"經濟學","topic":"經濟學","stem":"已知需求函數為Q 600 5P 0.6P 0.3P 4I x x yz ＝ −＋ − − ，其中Qx 為商品 X 的購買量，I 為所得，Px 為商品 X\n的價格，Py 為商品 Y 的價格，Pz 為商品 Z 的價格，則下列敘述何者正確？","options":["X 與 Y 為替代品","X 與 Z 為替代品","X 財違反需求法則","X 為正常財"],"answer":"A","official":"(A)  Py 前面係數為正數，表示 Py  →Y 的需求量 、\nX 的需求 ，X、Y 具替代性\n(B)  Pz 前面係數為負數，表示 Pz →Z 的需求量 、\nX 的需求 ，X、Z 具互補性\n(C)  Px 前面係數為負數，表示 Px  →X 的需求量 ，\nX 合乎需求法則\n(D) I 的前面是負數，表示 I  →X 的需求 ，X 為劣\n等財","scan":"data:image/webp;base64,"},{"id":"110-1-A-36","exam":"110-1","q":36,"unit":"經濟學","topic":"經濟學","stem":"假設一國只生產 X 與 Y 兩種財貨，則下列何種情況最能促進其經濟成長？","options":["利用閒置的資源","專業化生產 X 財貨或 Y 財貨","減少 X 財貨的生產，以增加 Y 財貨的生產","使用新的生產技術於 X 和 Y 財貨的生產"],"answer":"D","official":"(A) 利用閒置的資源只能使生產點由 PPC 線內，往\nPPC 線上移動\n(B) 專業化生產 X 或 Y，生產點落在 PPC 線在 X 或 Y\n軸上的點，PPC 線並未往外移動，不代表經濟成長\n(C) 減少 X 財貨的生產，以增加 Y 財貨的生產，是順\n著 PPC 往下移動，PPC 線並未往外移動，不代表經\n濟成長"},{"id":"110-1-A-37","exam":"110-1","q":37,"unit":"經濟學","topic":"經濟學","stem":"下列何者不屬於商業生產可以創增的效用？","options":["形式效用","地域效用","時間效用","產權效用"],"answer":"A"},{"id":"110-1-A-38","exam":"110-1","q":38,"unit":"經濟學","topic":"經濟學","stem":"探討「政府應否將高鐵延伸到屏東以提振當地觀光」及「新冠肺炎對臺灣就業率的影響」，下列敘述何\n者正確？","options":["皆屬規範經濟學","皆屬實證經濟學","前者屬規範經濟學，後者屬實證經濟學","前者屬實證經濟學，後者屬規範經濟學"],"answer":"C"},{"id":"110-1-A-39","exam":"110-1","q":39,"unit":"經濟學","topic":"經濟學","stem":"大明、大華、大強、大米各購買一個蘋果，願付的蘋果價格(willingness to pay)分別為：35 元、30 元、\n20 元、10 元。假設蘋果的市價為 18 元，則會付諸購買行動的消費者有幾人？","options":["1","2","3","4"],"answer":"C","official":"大明、大華、大強內心所願付出價格 市價→這三人\n會購買蘋果；大米內心所願付出價格  市價→大米不\n會購買"},{"id":"110-1-A-40","exam":"110-1","q":40,"unit":"經濟學","topic":"經濟學","stem":"假設香蕉的需求函數為Q 60 2P d ＝− ，水梨的供給函數為Q 12 2P S ＝ −＋ ，當 P 20 ＝ 時，香蕉的需求點彈\n性 d (E ) 與水梨的供給點彈性 S (E ) 分別為多少？","options":["E 10 d ＝ 、 S\n7 E\n10\n＝","E2 d ＝ 、 S\n10 E\n7 ＝","d\n1 E\n2 ＝ 、 S\n7 E\n10\n＝","d\n1 E\n10\n＝ 、 S\n10 E\n7 ＝"],"answer":"B","official":"d\n20 E2\n30 20 ＝ ＝ −\nS\n12 28 10 E\n28 7\n＋ ＝＝","scan":"data:image/webp;base64,"},{"id":"110-1-A-41","exam":"110-1","q":41,"unit":"經濟學","topic":"經濟學","stem":"下列敘述何者錯誤？","options":["需求曲線最早是由馬歇爾(Alfred Marshall)所提出","「需求創造供給」是由凱因斯(John Maynard Keynes)提出","經濟學鼻祖是李嘉圖(David Ricard)","第一次石油危機，產生停滯性通貨膨脹，提出解決方案的是供給面經濟學派"],"answer":"C","official":"(C) 經濟學鼻祖是亞當斯密(Adam Smith)","scan":"data:image/webp;base64,"},{"id":"110-1-A-42","exam":"110-1","q":42,"unit":"經濟學","topic":"經濟學","stem":"李同學準備英文與國文考試時，所花的準備時間與可獲得之分數如表(一)所示。若李同學只有四小時可\n準備，應如何分配時間，可使總分達到最高？\n表(一)\n時間／科目 英文 國文\n一小時 75 70\n二小時 82 78\n三小時 85 83","options":["英文一小時、國文三小時","英文及國文各兩小時","英文三小時、國文一小時","以上分配所得之總分皆相同"],"answer":"B","official":"英文及國文各兩小時的學習可使總分達到最高","scan":"data:image/webp;base64,"},{"id":"110-1-A-43","exam":"110-1","q":43,"unit":"經濟學","topic":"經濟學","stem":"AP 為平均產出，MP 為邊際產出，TP 為總產出，當①AP 的最高點、②TP 的最高點、③MP 的最高點，\n根據以上三種產量，可知廠商所投入的變動要素使用量，由小至大排列分別為何？","options":["①③②","②①③","③①②","③②①"],"answer":"C","official":"橫軸表示廠商投入的變動要素使用量，最高點從\nMP、AP、TP 依序出現，所以變動要素使用量由小至\n大排列為 MP、AP、TP"},{"id":"110-1-A-44","exam":"110-1","q":44,"unit":"經濟學","topic":"經濟學","stem":"2020 年的新冠肺炎疫情席捲全球，2021 年疫情更加嚴峻，遠端辦公、居家學習方興未艾，但全球晶片\n供應鏈應筆電廠商需求，配合擴大量能。但是筆電廠商即使增產，也無法因應市場大量的需求，針對筆\n電市場的供、需，請問下列哪一項是最有可能出現的結果？","options":["價格上漲、交易量減少","價格下跌、交易量增加","價格上漲、交易量增加","價格下跌、交易量減少"],"answer":"C","official":"遠端辦公、居家學習對筆電的需求增加；但晶片荒，\n使供應鏈反應不及，廠商勉強增產，造成 DS \n→ PQ "},{"id":"110-1-A-45","exam":"110-1","q":45,"unit":"經濟學","topic":"經濟學","stem":"下列敘述何者正確？","options":["其他情況不變，就同一點而言，當供給曲線愈平坦時，生產者剩餘愈大","生產可能曲線凹向原點的原因為機會成本遞增","人們逛街購物時，通常會貨比三家不吃虧，主要是希望增加邊際收益","政府對進口名牌包課稅，使得進口名牌包價格下跌"],"answer":"B","official":"(A) 在其他情況不變下，當供給曲線愈平坦時，生產\n者剩餘愈小\n(C) 貨比三家不吃虧，就是希望買到物超所值的財貨，\n消費者心理上會覺得賺了一些，這就是消費者剩餘\n(D) 課稅，供給曲線往左上方移動，造成價格上漲、\n交易量減少"},{"id":"110-1-A-46","exam":"110-1","q":46,"unit":"經濟學","topic":"經濟學","stem":"在生產三階段中，廠商在哪一階段生產，變動要素會產生負報酬？","options":["第一階段","第二階段","第三階段","以上皆不可能"],"answer":"C","official":"生產第三階段，MP 0  變動要素 ，變動要素發生報酬為負"},{"id":"110-1-A-47","exam":"110-1","q":47,"unit":"經濟學","topic":"經濟學","stem":"有關生產三階段的敘述，下列何者正確？","options":["在生產的第三階段， AP>MP>0", "第二階段為合理生產階段，變動要素發生邊際報酬遞減，但為正數", "在生產的第一階段，MP 上升", "在合理生產階段，當勞動僱用量達到最高限度時，此時 AP＝0， TP 最大"],"answer":"B","official":"(A) 生產的第三階段， AP 0 MP \n(C) 在生產的第一階段，AP 上升，MP 先遞增後遞減\n(D) 此時 MP 0 ＝ ，TP 最大","scan":"data:image/webp;base64,"},{"id":"110-1-A-48","exam":"110-1","q":48,"unit":"經濟學","topic":"經濟學","stem":"假設小戴對義美冰淇淋的邊際效用函數為 MU＝10−2Q， Q 表示冰淇淋的消費量，下列敘述何者不正確？","options":["小戴對冰淇淋的喜好，符合邊際效用遞減法則", "Q＝5 時，小戴消費冰淇淋可獲最大滿足，產生最大總效用", "小戴消費 4 支冰淇淋的總效用大於 3 支冰淇淋的總效用", "邊際效用曲線為負斜率的直線，總效用曲線為 U 字型"],"answer":"D","official":"(A)  MU 10 2Q ＝ − → Q MU  ，符合邊際效用遞減\n法則\n(B)  MU 0 ＝ →TU 最大，令10 2Q 0 −＝ → Q5 ＝ 時 TU\n最大\n(C)  Q4 ＝ 時 MU 2 ＝ →增加第 4 支冰淇淋，邊際效用\n 0 ，總效用繼續上升→ TU TU 43 \n(D) TU 效用曲線有最高點，是倒 U 字型","scan":"data:image/webp;base64,"},{"id":"110-1-A-49","exam":"110-1","q":49,"unit":"經濟學","topic":"經濟學","stem":"下列敘述何者正確？","options":["已知小蔡對文旦的需求函數為P 50 Q ＝− ，文旦價格為 30 元時，小蔡所願購買的最低數量為 20 單位","柚農阿成伯對文旦的供給函數為P 10 Q ＝ ＋ ，市場上文旦的供給共有 100 家柚農，其生產規模與阿成\n伯相同，則市場供給函數為 P 1000 100Q ＝＋","已知 XY\nXY\nMU MU 23\nPP ＝ ，根據邊際效用均等法則，消費者為獲最大滿足，應增加 Y 財貨購買量，減少\nX 財貨購買量","柳橙豐收，一台斤價格由去年的 20 元跌到 12 元，小郭對其購買量增加 10%，可知柳橙以弧彈性計\n算的價格變化的百分比，是下跌 50%"],"answer":"D","official":"(A) 小蔡所願購買的最多數量為 20 單位\n(B) 個人供給函數為 P 10 Q Q 10 ＝ ＋ ＝ − ＋ P\n市場供給函數為 Q ( 10 P) 100 1000 100P ＝ − ＋ × ＝− ＋\n(C)  XY\nXY\nMU MU 23\nPP ＝ →令 Y\nY\nMU\na\nP ＝ {a | a } 正實數\nX XY\nX XY\nMU MU MU 3\na\nP2 P P\n ＝ \n→增加 X 財貨購買量，減少 Y 財貨購買量\n[另解]\nXY\nXY\nMU MU 23\nPP ＝ XY\nXY\nMU MU 3\nP 2P\n ＝×\n→ X\nX\nMU\nP\n為 Y\nY\nMU\nP\n的 3\n2\n倍→ XY\nXY\nMU MU\nPP\n\n→增加 X 財貨購買量，減少 Y 財貨購買量\n(D) 柳橙豐收，一台斤價格由去年的 20 元跌到 12 元，\n價格變化% 12 20 50%\n(12 20) 2\n− ＝ ＝− ＋÷","scan":"data:image/webp;base64,"},{"id":"110-1-A-50","exam":"110-1","q":50,"unit":"經濟學","topic":"經濟學","stem":"已知 A 財貨的需求函數為P 100 2Q ＝− d ，供給函數為P 10 Q ＝ ＋ S ，若供給函數變動為P 16 Q ＝＋ S ，則下\n列敘述何者正確？","options":["可能是政府的補貼政策，導致供給曲線的移動","可能是生產技術進步，使供給函數發生變化","供給發生變化後，市場價格上漲了 6 元","社會福利因供給函數的變化而改變"],"answer":"D","official":"(A)  P 10 Q P 16 Q ＝ ＋ ＝ ＋ SS ，供給曲線平行往左上\n方移動，是政府對廠商課稅\n(B)  P 10 Q P 16 Q ＝ ＋ ＝ ＋ SS ，供給曲線平行往左上\n方移動，是供給減少；技術進步會造成供給增加\n(C) 解聯立 d\nS\nP 100 2Q\nP 10 Q\n\n\n\n＝−\n＝＋\n＝ P 40 、Q 30 ＝\n解聯立 d\nS\nP 100 2Q\nP 16 Q\n\n\n\n＝−\n＝＋\n＝ P 44 、Q 28 ＝\n故價格上漲 4 元\n(D) 畫圖可知，供給變動後\n社會福利由 (100 10) 30\n2\n−× ＝1350\n(100 16) 28 1176\n2\n−× ＝","scan":"data:image/webp;base64,"}]);
